/// <summary>
/// Example UPSPricingAttribute of table <c>InventDim</c> field wMSLocationId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventDimWMSLocationId_Product extends UPSPricingAttributeInventDim_Product implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, WMSLocationId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select WMSLocationId from inventDim
        group by WMSLocationId
    {
        ret.add(inventDim.WMSLocationId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, WMSLocationId));
    qbr.value(queryValue(_value));
}
